// 🤖 GEN Z EYE CHALLENGE AI ASSISTANT

let aiData = {
    games: 0,
        bestScore: 0,
            lastScore: 0
            };


            // AI Score Analyzer
            function analyzePlayer(score, time) {

                aiData.games++;
                    aiData.lastScore = score;

                        if (score > aiData.bestScore) {
                                aiData.bestScore = score;
                                    }

                                        let result;

                                            if (score >= 90) {
                                                    result = {
                                                                rank: "👑 Eye Legend",
                                                                            message: "Amazing focus! You are in the elite level.",
                                                                                        next: "Try AI Extreme Mode"
                                                                                                };
                                                                                                    }
                                                                                                        else if (score >= 70) {
                                                                                                                result = {
                                                                                                                            rank: "🔥 Focus Pro",
                                                                                                                                        message: "Great control! Your eyes are improving.",
                                                                                                                                                    next: "Try harder challenges"
                                                                                                                                                            };
                                                                                                                                                                }
                                                                                                                                                                    else if (score >= 40) {
                                                                                                                                                                            result = {
                                                                                                                                                                                        rank: "😎 Eye Fighter",
                                                                                                                                                                                                    message: "Good attempt. Practice makes you better.",
                                                                                                                                                                                                                next: "Keep training"
                                                                                                                                                                                                                        };
                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                else {
                                                                                                                                                                                                                                        result = {
                                                                                                                                                                                                                                                    rank: "😂 Blink Master",
                                                                                                                                                                                                                                                                message: "Your eyes need more focus practice.",
                                                                                                                                                                                                                                                                            next: "Try easy mode"
                                                                                                                                                                                                                                                                                    };
                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                            return result;
                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                            // AI Challenge Generator
                                                                                                                                                                                                                                                                                            function createChallenge() {

                                                                                                                                                                                                                                                                                                let challenges = [
                                                                                                                                                                                                                                                                                                        "👀 No Blink Challenge",
                                                                                                                                                                                                                                                                                                                "⚡ Fast Focus Challenge",
                                                                                                                                                                                                                                                                                                                        "🧠 Memory Eye Test",
                                                                                                                                                                                                                                                                                                                                "🔥 Ultimate Concentration",
                                                                                                                                                                                                                                                                                                                                        "🏆 Legend Eye Battle"
                                                                                                                                                                                                                                                                                                                                            ];

                                                                                                                                                                                                                                                                                                                                                return challenges[Math.floor(Math.random()*challenges.length)];
                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                // AI Questions For Players
                                                                                                                                                                                                                                                                                                                                                function askPlayerQuestion(){

                                                                                                                                                                                                                                                                                                                                                    let questions = [
                                                                                                                                                                                                                                                                                                                                                            "👀 How long can you focus without blinking?",
                                                                                                                                                                                                                                                                                                                                                                    "🔥 Can you beat your previous score?",
                                                                                                                                                                                                                                                                                                                                                                            "🎮 Are you ready for a harder challenge?",
                                                                                                                                                                                                                                                                                                                                                                                    "🏆 What is your target score today?"
                                                                                                                                                                                                                                                                                                                                                                                        ];

                                                                                                                                                                                                                                                                                                                                                                                            return questions[Math.floor(Math.random()*questions.length)];
                                                                                                                                                                                                                                                                                                                                                                                            }


                                                                                                                                                                                                                                                                                                                                                                                            // AI Chat Assistant
                                                                                                                                                                                                                                                                                                                                                                                            function genZAIChat(userMessage){

                                                                                                                                                                                                                                                                                                                                                                                                let text = userMessage.toLowerCase();

                                                                                                                                                                                                                                                                                                                                                                                                    if(text.includes("score")){
                                                                                                                                                                                                                                                                                                                                                                                                            return "Your goal is simple: beat your best score and become an Eye Legend 👑";
                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                    if(text.includes("how")){
                                                                                                                                                                                                                                                                                                                                                                                                                            return "Focus on the screen and challenge yourself. The better your focus, the higher your score 👀";
                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                    if(text.includes("challenge")){
                                                                                                                                                                                                                                                                                                                                                                                                                                            return "Today's AI challenge: " + createChallenge();
                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    if(text.includes("hello") || text.includes("hi")){
                                                                                                                                                                                                                                                                                                                                                                                                                                                            return "Hey 👋 I am Gen Z AI Assistant. Ready for your eye challenge?";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return "Interesting! Try the challenge and ask me about your score, level, or game tips 🤖";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // AI Motivation
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function aiMotivation(){

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let words=[
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "🔥 You can beat your record!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "👀 Stay focused!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "⚡ One more try!",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "🏆 Champions keep improving!"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return words[Math.floor(Math.random()*words.length)];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Player Statistics
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function getPlayerStats(){

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            gamesPlayed: aiData.games,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    bestScore: aiData.bestScore,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            lastScore: aiData.lastScore
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


