                                                                                                                                                                                                                                                                                                                                                                         // AI Player Profile
                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                         let finalAIProfile = {
                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                             totalGames: 0,
                                                                                                                                                                                                                                                                                                                                                                                 totalScore: 0,
                                                                                                                                                                                                                                                                                                                                                                                     highestScore: 0,
                                                                                                                                                                                                                                                                                                                                                                                         improvement: 0,
                                                                                                                                                                                                                                                                                                                                                                                             favoriteMode: "Classic"
                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                             };
                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                             // =================================
                                                                                                                                                                                                                                                                                                                                                                                             // AI PERFORMANCE ANALYZER
                                                                                                                                                                                                                                                                                                                                                                                             // =================================
                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                             function advancedAIAnalysis(score, time){
                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                 finalAIProfile.totalGames++;
                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                     finalAIProfile.totalScore += score;
                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                         if(score > finalAIProfile.highestScore){
                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                 finalAIProfile.highestScore = score;
                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                         let average =
                                                                                                                                                                                                                                                                                                                                                                                                                             Math.round(
                                                                                                                                                                                                                                                                                                                                                                                                                                     finalAIProfile.totalScore /
                                                                                                                                                                                                                                                                                                                                                                                                                                             finalAIProfile.totalGames
                                                                                                                                                                                                                                                                                                                                                                                                                                                 );
                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                     return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                             currentScore: score,
                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                     highestScore:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                             finalAIProfile.highestScore,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     averageScore:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             average,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     focusLevel:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             aiFocusLevel(score),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     advice:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             aiAdvice(score)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 // =================================
